import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-10-30 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-10-30 :: Ceph Orchestration Meeting","date":"2019-10-30T00:00:00.000Z","updated":"2019-11-04T00:00:00.000Z","tags":["Ceph","分布式存储","系统监控","集群管理","软件集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-30_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-10-30_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-10-30_-_-_Ceph_Orchestration_Meeting.md"};function o(a,t,s,p,_,h){return l(),i("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph分布式存储项目讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未知）</p><p><strong>参会人员</strong>：</p><ul><li>Sun、CH、Letta Pia、Katy Wiseman、Edie、Paul Kozma、AJ、Sage Ki Foo、Brad Hubbard、会议记录者</li></ul><p><strong>会议关键细节</strong>：</p><p><strong>1. Python 3问题</strong>：</p><ul><li>在Sintra 7和Central US 8环境中，由于CentOS 7缺少Python 3的某些包，导致Ceph无法运行。</li><li>讨论了在CentOS 7中添加所需Python 3包的可能性，并建议由Ceph项目成员提交请求。</li></ul><p><strong>2. Ceph集群状态监控</strong>：</p><ul><li>提出了一个用于监控Ceph集群状态的工具，使用一种未命名的数据结构存储状态信息。</li><li>讨论了使用OC metadata来改进数据结构，并计划未来进行改进。</li></ul><p><strong>3. 设备共享问题</strong>：</p><ul><li>讨论了当多个设备共享同一个OSD时可能出现的冲突问题。</li><li>提出了使用CID来区分不同设备的建议。</li></ul><p><strong>4. SSH Orchestrator集成</strong>：</p><ul><li>CH正在努力集成SSH Orchestrator，但由于CentOS 7缺少Python 3的某些包，导致集成受阻。</li><li>讨论了使用远程IO包的兼容性问题。</li></ul><p><strong>5. 人员变动</strong>：</p><ul><li>会议记录者将在2023年12月至2月期间离职。</li><li>讨论了在离职前如何为团队做出贡献。</li></ul><p><strong>决定事项</strong>：</p><ul><li>由Ceph项目成员提交请求，在CentOS 7中添加所需Python 3包。</li><li>进一步改进Ceph集群状态监控工具。</li><li>使用CID来区分共享同一个OSD的不同设备。</li><li>寻找解决方案以解决SSH Orchestrator集成问题。</li><li>讨论了离职人员的贡献问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>由Ceph项目成员提交请求，在CentOS 7中添加所需Python 3包。</li><li>进一步改进Ceph集群状态监控工具。</li><li>使用CID来区分共享同一个OSD的不同设备。</li><li>寻找解决方案以解决SSH Orchestrator集成问题。</li><li>讨论了离职人员的贡献问题。</li></ul><p>[改进后的总结确保了以下几点：]</p><ul><li>准确反映了原始内容的关键细节。</li><li>覆盖了讨论的主要议题。</li><li>提到了决定的事项和后续的行动计划。</li><li>保留了计算机科学/ceph相关领域的英文原文关键词。</li></ul>',22)])])}const C=e(n,[["render",o]]);export{u as __pageData,C as default};
